package com.networkers.meetingautomation; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface MonthlyMeetingRepository extends JpaRepository<MonthlyMeeting,Long>{ Optional<MonthlyMeeting> findByGroupId(Long groupId); List<MonthlyMeeting> findByScheduledDateAndReminderSentFalse(java.time.LocalDate date); List<MonthlyMeeting> findByGroupChapterIdAndGroupYearAndGroupMonthOrderByGroupGroupNumber(Long chapterId,int year,int month); List<MonthlyMeeting> findByGroupCycleIdOrderByScheduledDateAscGroupGroupNumberAsc(Long cycleId); @Modifying @Query("delete from MonthlyMeeting m where m.group.id=:groupId") void deleteByGroupId(@Param("groupId") Long groupId); }
